"use client";
import Loader from "@/components/Loader";
import DoctorAppointmentDetail from "@/components/doctor/DoctorAppointmentDetail";
import { userAuthStore } from "@/store/authStores";
import { useParams, useRouter } from "next/navigation";
import { useEffect } from "react";

export default function DoctorAppointmentDetailPage() {
  const router = useRouter();
  const params = useParams<{ id: string }>();
  const { user, isAuthenticated } = userAuthStore();

  useEffect(() => {
    if (!isAuthenticated || !user) {
      router.push("/login/doctor");
    } else if (user.type !== "doctor") {
      router.push(user.type === "patient" ? "/patient/appointments" : "/admin/dashboard");
    }
  }, [isAuthenticated, user, router]);

  if (!isAuthenticated || !user || user.type !== "doctor") {
    return <Loader />;
  }

  return <DoctorAppointmentDetail appointmentId={params.id} />;
}

