"use client";

export const dynamic = "force-dynamic";

import { useState, useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { userAuthStore } from "@/store/authStores";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import {
  Clock,
  Calendar,
  Save,
  Plus,
  Trash2,
  ArrowLeft,
  User,
  Lock,
  Bell,
  CreditCard,
  Eye,
  EyeOff,
  ShieldCheck,
  ShieldOff,
  Monitor,
  LogOut,
  CheckCircle2,
  XCircle,
  History,
  Copy,
  Camera,
} from "lucide-react";
import httpService from "@/services/httpsServices";
import Loader from "@/components/Loader";
import Header from "@/components/landing/header";
import ImageCropDialog from "@/components/ImageCropDialog";

interface TimeRange {
  start: string;
  end: string;
}

interface AvailabilityRange {
  startDate: string;
  endDate: string;
  excludedWeekdays: number[];
}

function DoctorSettingsContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user } = userAuthStore();
  const { toast } = useToast();

  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("profile");

  const [disablePassword, setDisablePassword] = useState("");
  const [disabling2FA, setDisabling2FA] = useState(false);

  // ── Security: Sessions ─────────────────────────────────────────
  const [sessions, setSessions] = useState<any[]>([]);
  const [sessionsLoading, setSessionsLoading] = useState(false);

  // ── Security: Login History ────────────────────────────────────
  const [loginHistory, setLoginHistory] = useState<any[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  // ── Notification Preferences ────────────────────────────────────────
  const defaultPrefs = {
    emailNewBooking: true,
    emailCancellation: true,
    emailSessionReminder24h: true,
    emailSessionReminder1h: true,
    emailNewMessage: true,
    weeklyDigest: true,
  };
  const [notifPrefs, setNotifPrefs] = useState<typeof defaultPrefs>(defaultPrefs);
  const [notifSaving, setNotifSaving] = useState<string | null>(null);

  useEffect(() => {
    // Check authentication
    if (!user || user.type !== "doctor") {
      router.push("/login/doctor");
      return;
    }

    // Check verification status
    if (user.verificationStatus !== 'approved' || !user.isVerified) {
      router.push("/doctor/pending-approval");
      return;
    }

    // Set active tab from URL params
    const tab = searchParams.get("tab");
    if (tab) {
      setActiveTab(tab);
    }

    // Load user data
    if (user) {
      const rawPhone = user.phone || "";
      const digits = rawPhone.replace(/^\+91\s?/, "").replace(/\s/g, "");
      setPhoneDigits(digits);

      const titleOptions = ["Dr.", "Mr.", "Ms.", "Prof.", "Mx."];
      const nameParts = (user.name || "").split(" ");
      let title = "Dr.";
      let firstName = "";
      let lastName = "";
      if (nameParts.length > 0 && titleOptions.includes(nameParts[0])) {
        title = nameParts[0];
        const rest = nameParts.slice(1);
        firstName = rest.length > 1 ? rest.slice(0, -1).join(" ") : rest[0] || "";
        lastName = rest.length > 1 ? rest[rest.length - 1] : "";
      } else {
        firstName = nameParts[0] || "";
        lastName = nameParts.slice(1).join(" ");
      }
      setTwoFactorEnabled(false);
      setDisablePassword("");
      toast({ title: "2FA disabled", description: "Two-factor authentication has been turned off." });
    } catch (err: any) {
      toast({ title: "Error", description: err.message || "Incorrect password.", variant: "destructive" });
    } finally {
      setDisabling2FA(false);
    }
  };

  const handleRevokeSession = async (sessionId: string) => {
    try {
      await httpService.delete(`/doctor/security/sessions/${sessionId}`);
      setSessions((prev) => prev.filter((s) => s.id !== sessionId));
      toast({ title: "Session revoked", description: "That device has been logged out." });
    } catch (err: any) {
      toast({ title: "Error", description: err.message || "Failed to revoke session.", variant: "destructive" });
    }
  };

  const handleRevokeAllSessions = async () => {
    try {
      await httpService.delete("/doctor/security/sessions");
      setSessions((prev) => prev.filter((s) => s.isCurrent));
      toast({ title: "All other devices logged out", description: "Only your current session remains active." });
    } catch (err: any) {
      toast({ title: "Error", description: err.message || "Failed to revoke sessions.", variant: "destructive" });
    }
  };

  const handleTogglePref = async (key: keyof typeof defaultPrefs, value: boolean) => {
    // Optimistic update
    setNotifPrefs((prev) => ({ ...prev, [key]: value }));
    setNotifSaving(key);
    try {
      await httpService.put("/doctor/notification-prefs", { [key]: value });
    } catch (err: any) {
      // Revert on failure
      setNotifPrefs((prev) => ({ ...prev, [key]: !value }));
      toast({ title: "Error", description: err.message || "Failed to update preference.", variant: "destructive" });
    } finally {
      setNotifSaving(null);
    }
  };

  // Load notification prefs when notifications tab activated
  useEffect(() => {
    if (activeTab === "notifications" && user) {
      httpService.get("/doctor/notification-prefs")
        .then((res) => {
          if (res.data) setNotifPrefs((prev) => ({ ...prev, ...res.data }));
        })
        .catch(() => {});
    }
  }, [activeTab, user]);

  // Load security data when Security tab is activated
  useEffect(() => {
    if (activeTab === "security" && user) {
      const loadSecurity = async () => {
        setSessionsLoading(true);
        setHistoryLoading(true);
      // Validate time ranges
      for (const range of dailyTimeRanges) {
        if (!range.start || !range.end) {
          toast({
            title: "Validation Error",
            description: "Please fill in all time ranges",
            variant: "destructive",
          });
          return;
        }

        if (range.start >= range.end) {
          toast({
            title: "Validation Error",
            description: "End time must be after start time",
            variant: "destructive",
          });
          return;
        }
      }

      const updateData = {
        dailyTimeRanges,
        availabilityRange,
        slotDurationMinutes,
      };

      const response = await httpService.put("/doctor/onboarding/update", updateData);

      // Update store directly from response — skip redundant fetchProfile round trip
      const { user: currentUser } = userAuthStore.getState();
      if (currentUser) {
        userAuthStore.setState({
          user: { ...currentUser, ...response.data, type: currentUser.type },
        });
      }

      toast({
        title: "Success",
        description: "Availability settings saved successfully",
      });
    } catch (error: any) {
      console.error("Error saving availability:", error);
      toast({
        title: "Error",
        description: error.message || "Failed to save availability settings",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSaveProfile = async () => {
    try {
      setLoading(true);

      // Validate bio length
      if (profileData.about.trim().length < 100) {
        toast({
          title: "Bio too short",
          description: "Please write at least 100 characters in your bio.",
          variant: "destructive",
        });
        setLoading(false);
        return;
      }

      // Validate phone
      if (!/^[6-9]\d{9}$/.test(phoneDigits)) {
        toast({
          title: "Invalid phone number",
          description: "Please enter a valid 10-digit Indian mobile number.",
          variant: "destructive",
        });
        setLoading(false);
        return;
      }

      const composedName = [profileTitle, profileFirstName, profileLastName]
        .filter(Boolean)
        .join(" ");

      const updateData: Record<string, any> = {
        name: composedName,
        phone: `+91${phoneDigits}`,
        about: profileData.about,

      const response = await httpService.put("/doctor/onboarding/update", updateData);

      // Update store directly from response — no need for a second fetchProfile round trip
      const { user: currentUser } = userAuthStore.getState();
      if (currentUser) {
        userAuthStore.setState({
          user: { ...currentUser, ...response.data, type: currentUser.type },
        });
      }
      setProfileImageFile(null);

      toast({
        title: "Success",
        description: "Profile updated successfully",
      });
    } catch (error: any) {
      console.error("Error updating profile:", error);
      toast({
        title: "Error",
        description: error.message || "Failed to update profile",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  if (!user) {
    return <Loader />;
  }

  const weekdays = [
    { label: "Mon", value: 1 },
    { label: "Tue", value: 2 },
    { label: "Wed", value: 3 },
    { label: "Thu", value: 4 },
    { label: "Fri", value: 5 },
    { label: "Sat", value: 6 },
    { label: "Sun", value: 0 },
  ];

  return (
    <div className="min-h-screen bg-background">
      <Header showDashboardNav={true} />
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Page Header */}
        <div className="flex items-center gap-4 mb-6">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => router.back()}
            aria-label="Go back"
          >
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-foreground">Settings</h1>
            <p className="text-muted-foreground mt-1">
              Manage your profile and preferences
            </p>
          </div>
                      </p>
                    </div>
                  ) : (
                    <p className="text-xs text-muted-foreground">
                      Voice calls charged at the same rate as video consultations
                    </p>
                  )}
                </div>

                {/* Bio with counter */}
                <div className="space-y-2">
                  <Label htmlFor="about">About / Bio</Label>
                  <textarea
                    id="about"
                    className="w-full min-h-[120px] rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    value={profileData.about}
                    onChange={(e) => {
                      if (e.target.value.length <= 800)
                        setProfileData({ ...profileData, about: e.target.value });
                    }}
                    placeholder="Tell patients about your approach and experience..."
                  />
                  <div className="flex justify-between text-xs">
                    {profileData.about.length < 100 ? (
                      <span className="text-destructive">
                        {100 - profileData.about.length} more characters needed (minimum 100)
                      </span>
                    ) : (
                      <span className="text-green-600">✓ Looks good</span>
                    )}
                    <span className="text-muted-foreground">
                      {profileData.about.length}/800
                    </span>
                  </div>
                </div>

                <Separator />

                <div className="flex justify-end">
                  <Button onClick={handleSaveProfile} disabled={loading}>
                    {loading ? (
                      <>
                        <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin mr-2" />
                        Saving...
                      </>
                    ) : (
                      <>
                        <Save className="w-4 h-4 mr-2" />
                        Save Changes
                      </>
                    )}
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* Professional Information Card */}
            <Card>
              <CardHeader>
                <CardTitle>Professional Information</CardTitle>
                <CardDescription>
                  Add your credentials, specialisations, and languages
                      </>
                    )}
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Availability Tab */}
          <TabsContent value="availability">
            <Card>
              <CardHeader>
                <CardTitle>Your Availability</CardTitle>
                <CardDescription>
                  Configure when patients can book appointments with you
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">

                {/* Session Duration */}
                <div className="space-y-3">
                  <Label className="text-base font-medium">Session Duration</Label>
                  <div className="flex flex-wrap gap-2">
                    {[30, 45, 50, 60].map((mins) => (
                      <button
                        key={mins}
                        type="button"
                        onClick={() => setSlotDurationMinutes(mins)}
                        className={`px-5 py-2 rounded-full text-sm font-medium transition-colors border ${
                          slotDurationMinutes === mins
                            ? "bg-primary text-primary-foreground border-primary"
                            : "bg-background text-foreground border-border hover:border-primary hover:text-primary"
                        }`}
                      >
                        {mins} min
                      </button>
                    ))}
                  </div>
                </div>

                <Separator />

                {/* Working Days */}
                <div className="space-y-3">
                  <div>
                    <Label className="text-base font-medium">Working Days</Label>
                    <p className="text-xs text-muted-foreground mt-0.5">Select the days you see patients</p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {weekdays.map((day) => {
                      const isWorking = !availabilityRange.excludedWeekdays.includes(day.value);
                      return (
                        <button
                          key={day.value}
                          type="button"
                          onClick={() => handleToggleWeekday(day.value)}
                          className={`px-4 py-2 rounded-full text-sm font-medium transition-colors border flex items-center gap-1.5 ${
                            isWorking
                              ? "bg-primary text-primary-foreground border-primary"
                              : "bg-background text-muted-foreground border-border"
                          }`}
                        >
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </CardContent>
            </Card>

          </TabsContent>

          {/* Notifications Tab */}
          <TabsContent value="notifications" className="space-y-6">
            {/* Appointments */}
            <Card>
              <CardHeader>
                <CardTitle>Appointments</CardTitle>
                <CardDescription>Email alerts related to your sessions</CardDescription>
              </CardHeader>
              <CardContent className="divide-y divide-border">
                {[
                  { key: "emailNewBooking" as const, label: "New booking", sub: "When a patient books an appointment with you" },
                  { key: "emailCancellation" as const, label: "Cancellation", sub: "When a patient cancels or reschedules" },
                  { key: "emailSessionReminder24h" as const, label: "24-hour reminder", sub: "Reminder the day before each session" },
