// File: page.tsx
// Purpose: My Appointments page - separate page for viewing all patient appointments
"use client";
import PatientDashboardContent from "@/components/patient/PatientDashboardContent";
import Loader from "@/components/Loader";
import { userAuthStore } from "@/store/authStores";
import { useRouter } from "next/navigation";
import { useEffect } from "react";

export default function MyAppointmentsPage() {
  const router = useRouter();
  const { user, isAuthenticated } = userAuthStore();

  useEffect(() => {
    // Protect this route - redirect to login if not authenticated
    if (!isAuthenticated || !user) {
      router.push("/login/patient");
    } else if (user.type !== "patient") {
      // If user is authenticated but not a patient, redirect to their dashboard  
      router.push(user.type === "doctor" ? "/doctor/dashboard" : "/admin/dashboard");
    }
  }, [isAuthenticated, user, router]);

  // Show loader while checking authentication
  if (!isAuthenticated || !user || user.type !== "patient") {
    return <Loader />;
  }

  return <PatientDashboardContent />;
}

