"use client";
import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { AlertCircle, XCircle, CheckCircle2 } from "lucide-react";
import { useAppointmentStore } from "@/store/appointmentStore";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useToast } from "@/hooks/use-toast";

interface CancelAppointmentDialogProps {
  appointmentId: string;
  appointmentDate: string;
  trigger: React.ReactNode;
  onSuccess?: () => void;
}

const CancelAppointmentDialog = ({
  appointmentId,
  appointmentDate,
  trigger,
  onSuccess,
}: CancelAppointmentDialogProps) => {
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState("");
  const [loading, setLoading] = useState(false);
  const { cancelAppointment } = useAppointmentStore();
  const { toast } = useToast();

  const calculateRefundInfo = () => {
    const appointmentTime = new Date(appointmentDate);
    const now = new Date();
    const hoursUntilAppointment = (appointmentTime.getTime() - now.getTime()) / (1000 * 60 * 60);

    if (hoursUntilAppointment >= 24) {
      return {
        eligible: true,
        percentage: 100,
        message: "You will receive a 100% refund"
      };
    } else if (hoursUntilAppointment >= 2) {
      return {
        eligible: true,
        percentage: 50,
        message: "You will receive a 50% refund (cancelled less than 24 hours before appointment)"
      };
    } else {
      return {
        eligible: false,
        percentage: 0,
        message: "No refund available (cancellations less than 2 hours before appointment)"
      };
    }
  };

  const refundEstimate = calculateRefundInfo();

  const handleCancel = async () => {
    if (!reason.trim()) {
      return;
    }

    setLoading(true);
    try {
      const response = await cancelAppointment(appointmentId, reason);

      // Show success toast
      toast({
        variant: "success",
        title: "✓ Appointment Cancelled Successfully",
        description: response?.refundInfo?.message || "Your appointment has been cancelled.",
        duration: 5000,
      });

      // Close dialog and reset
      setOpen(false);
      setReason("");

      // Call onSuccess callback to refresh the list
      onSuccess?.();
    } catch (error: any) {
      console.error("Failed to cancel appointment:", error);

      // Show error toast
      toast({
        variant: "destructive",
        title: "Cancellation Failed",
        description: error?.message || "Failed to cancel appointment. Please try again.",
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{trigger}</DialogTrigger>
      <DialogContent className="sm:max-w-[500px] bg-background border-border">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-red-600 dark:text-red-500">
            <XCircle className="w-5 h-5" />
            Cancel Appointment
          </DialogTitle>
          <DialogDescription className="text-foreground/80 dark:text-foreground/70">
            Are you sure you want to cancel this appointment? This action cannot be undone.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Refund Policy Info */}
          <Alert className={refundEstimate.eligible 
            ? "border-blue-500/50 bg-blue-500/10 dark:bg-blue-500/20 dark:border-blue-400/50" 
            : "border-amber-500/50 bg-amber-500/10 dark:bg-amber-500/20 dark:border-amber-400/50"
          }>
            <AlertCircle className={`h-4 w-4 ${refundEstimate.eligible ? "text-blue-600 dark:text-blue-400" : "text-amber-600 dark:text-amber-400"}`} />
            <AlertDescription className={refundEstimate.eligible 
              ? "text-blue-900 dark:text-blue-200 font-medium" 
              : "text-amber-900 dark:text-amber-200 font-medium"
            }>
              <strong className="font-semibold">Refund Policy:</strong> {refundEstimate.message}
            </AlertDescription>
          </Alert>

          {/* Cancellation Reason */}
          <div className="space-y-2">
            <Label htmlFor="reason" className="text-foreground font-medium">
              Cancellation Reason <span className="text-red-500 dark:text-red-400">*</span>
            </Label>
            <Textarea
              id="reason"
              placeholder="Please provide a reason for cancellation (e.g., schedule conflict, medical emergency, etc.)"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              rows={4}
              maxLength={500}
              className="resize-none bg-background border-input text-foreground placeholder:text-muted-foreground"
            />
            <p className="text-xs text-muted-foreground/80 dark:text-muted-foreground text-right">
              {reason.length}/500 characters
            </p>
          </div>

          {/* Policy Details */}
          <div className="bg-muted/50 dark:bg-muted/80 p-4 rounded-md text-sm space-y-2 border border-border/50">
            <p className="font-semibold text-foreground">Cancellation Policy:</p>
            <ul className="list-disc list-inside space-y-1.5 text-foreground/70 dark:text-foreground/80">
              <li className="leading-relaxed">24+ hours before: 100% refund</li>
              <li className="leading-relaxed">2-24 hours before: 50% refund</li>
              <li className="leading-relaxed">Less than 2 hours: No refund</li>
              <li className="leading-relaxed">Refunds processed within 5-7 business days</li>
            </ul>
          </div>
        </div>

        <DialogFooter className="gap-2">
          <Button
            type="button"
            variant="outline"
            onClick={() => setOpen(false)}
            disabled={loading}
            className="border-border hover:bg-accent hover:text-accent-foreground"
          >
            Keep Appointment
          </Button>
          <Button
            type="button"
            variant="destructive"
            onClick={handleCancel}
            disabled={!reason.trim() || loading}
            className="bg-red-600 hover:bg-red-700 dark:bg-red-600 dark:hover:bg-red-700"
          >
            {loading ? "Cancelling..." : "Cancel Appointment"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default CancelAppointmentDialog;

