"use client";
import React, { useEffect, useMemo, useState } from "react";
import Header from "../landing/header";
import { userAuthStore } from "@/store/authStores";
import { Appointment, useAppointmentStore } from "@/store/appointmentStore";
import { Card, CardContent } from "../ui/card";
import Link from "next/link";
import { Button } from "../ui/button";
import { Calendar, Clock, FileText, MapPin, Phone, Star, Video, XCircle } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import { Avatar, AvatarFallback, AvatarImage } from "../ui/avatar";
import { Badge } from "../ui/badge";
import { getStatusColor } from "@/lib/constant";
import PrescriptionViewModal from "../doctor/PrescriptionViewModal";
import CancelAppointmentDialog from "../CancelAppointmentDialog";
import MeetingButton from "../MeetingButton";
import { useToast } from "@/hooks/use-toast";

const PatientDashboardContent = () => {
  const { user } = userAuthStore();
  const { appointments, fetchAppointments, loading } = useAppointmentStore();
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState("upcoming");

  useEffect(() => {
    if (user?.type === "patient") {
      fetchAppointments("patient");
    }
  }, [user, fetchAppointments]);

  // Mirror the backend's tab classification so both counts are correct from
  // the first render — fetching one tab at a time left the other tab's badge
  // stuck at 0 until the user clicked it.
  const { upcomingList, pastList } = useMemo(() => {
    const startOfToday = new Date();
    startOfToday.setHours(0, 0, 0, 0);
    const isLive = (a: Appointment) => a.status === "Scheduled" || a.status === "In Progress";
    const isFuture = (a: Appointment) =>
      new Date(a.date || a.slotStartIso) >= startOfToday;

    const upcoming = appointments.filter((a) => isLive(a) && isFuture(a));
    const past = appointments.filter(
      (a) => a.status === "Completed" || a.status === "Cancelled" || (isLive(a) && !isFuture(a))
    );
    return { upcomingList: upcoming, pastList: past };
  }, [appointments]);

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("en-IN", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const isToday = (dateString: string) => {
    const today = new Date();
    const appointmentDate = new Date(dateString);
    return appointmentDate.toDateString() === today.toDateString();
  };

  if (!user) {
    return null;
  }

  const AppointmentCard = ({ appointment }: { appointment: Appointment }) => (
    <Card className="group hover:shadow-xl transition-all duration-300 border-0 shadow-md bg-linear-to-br from-card to-card/80 overflow-hidden">
      <CardContent className="p-0">
        <div className="flex flex-col items-center md:flex-row md:items-start">
          {/* Avatar Section with gradient background */}
          <div className="w-full md:w-auto p-6 pb-4 md:pb-6 shrink-0 flex justify-center md:justify-start bg-linear-to-br from-primary/5 to-transparent">
            <Avatar className="w-20 h-20 ring-4 ring-background shadow-lg">
              <AvatarImage
                src={appointment.doctorId?.profileImage}
                alt={appointment.doctorId?.name}
                className="object-cover"
              />
              <AvatarFallback className="bg-linear-to-br from-primary to-primary/70 text-primary-foreground text-xl font-bold">
                {appointment.doctorId?.name?.charAt(0)?.toUpperCase()}
              </AvatarFallback>
            </Avatar>
          </div>

          <div className="flex-1 w-full p-6 pt-2 md:pt-6 md:pl-2">
            {/* Header with name and status */}
            <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-3">
              <div className="text-center md:text-left">
                <h3 className="text-xl font-semibold text-foreground tracking-tight font-display">
                  {appointment.doctorId?.name}
                </h3>
                <p className="text-sm font-medium text-primary/80 mt-0.5">
                  {appointment.doctorId?.specialization}
                </p>
                <div className="flex items-center justify-center md:justify-start gap-1.5 text-xs text-muted-foreground mt-2">
                  <MapPin className="w-3.5 h-3.5" />
                  <span className="truncate max-w-[150px] sm:max-w-[200px] md:max-w-[300px]">{appointment.doctorId?.hospitalInfo?.name}</span>
                </div>
              </div>

              <div className="flex flex-col items-center md:items-end gap-1.5">
                <Badge className={`${getStatusColor(appointment.status)} font-medium px-3 py-1 text-xs shadow-sm`}>
                  {appointment.status}
                </Badge>
                {isToday(appointment.slotStartIso) && (
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 uppercase tracking-wider">
                    Today
                  </span>
                )}
              </div>
            </div>

            {/* Appointment Details Grid */}
            <div className="mt-5 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-3">
                <div className="flex items-center justify-center md:justify-start gap-2.5 text-sm">
                  <div className="p-1.5 rounded-md bg-muted">
                    <Calendar className="w-4 h-4 text-primary" />
                  </div>
                  <span className="text-foreground/80 font-medium text-xs sm:text-sm">{formatDate(appointment.slotStartIso)}</span>
                </div>

                <div className="flex items-center justify-center md:justify-start gap-2.5 text-sm">
                  <div className="p-1.5 rounded-md bg-muted">
                    {appointment.consultationType === "Video Consultation" ? (
                      <Video className="w-4 h-4 text-primary" />
                    ) : (
                      <Phone className="w-4 h-4 text-primary" />
                    )}
                  </div>
                  <span className="text-foreground/80 font-medium">{appointment.consultationType}</span>
                </div>
              </div>

              <div className="space-y-3 text-center md:text-left">
                  {appointment.doctorId?.fees ? (
                    <div className="flex items-center justify-center md:justify-start gap-2">
                      <span className="text-xs uppercase tracking-wider text-muted-foreground font-semibold">Fee:</span>
                      <span className="text-lg font-bold text-foreground tabular-nums">₹{appointment.doctorId.fees}</span>
                    </div>
                  ) : null}
              </div>
            </div>

            {/* Show cancellation info if cancelled */}
            {appointment.status === 'Cancelled' && (
              <div className="mt-5 p-4 bg-linear-to-r from-red-50 to-red-50/50 dark:from-red-950/30 dark:to-red-950/10 border border-red-200/50 dark:border-red-800/30 rounded-xl">
                <p className="text-sm text-red-700 dark:text-red-400 font-semibold flex items-center gap-2">
                  <span className="w-5 h-5 rounded-full bg-red-100 dark:bg-red-900/50 flex items-center justify-center text-xs">⚠️</span>
                  This appointment was cancelled
                </p>
                {appointment.cancellationReason && (
                  <p className="text-xs text-red-600/80 dark:text-red-400/70 mt-2 pl-7 leading-relaxed">
                    Reason: {appointment.cancellationReason}
                  </p>
                )}
              </div>
            )}

            {/* Action Buttons */}
            <div className="mt-6 pt-4 border-t border-border/50 flex flex-col md:flex-row items-center md:justify-between gap-3">

            <div className="flex flex-wrap gap-2 justify-center md:justify-start">
              <MeetingButton
                appointment={appointment}
                userType="patient"
                onMeetingCreated={() => {
                  toast({
                    title: "Meeting link available",
                    description: "Your therapist has created a Google Meet link for this session.",
                  });
                  fetchAppointments("patient");
                }}
                onError={(message) => {
                  toast({
                    title: "Meeting action failed",
                    description: message,
                    variant: "destructive",
                  });
                }}
              />

              {appointment.status === 'Completed' && appointment.prescription && (
                <PrescriptionViewModal
                  appointment={appointment}
                  userType="patient"
                  trigger={
                    <Button
                      variant='outline'
                      size='sm'
                      className="text-emerald-700 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800 hover:bg-emerald-50 dark:hover:bg-emerald-950/50 font-medium transition-colors"
                    >
                      <FileText className="w-4 h-4 mr-2"/>
                      View Prescription
                    </Button>
                  }
                />
              )}

              {appointment.status === 'Scheduled' && new Date(appointment.slotEndIso) > new Date() && (
                <CancelAppointmentDialog
                  appointmentId={appointment._id}
                  appointmentDate={appointment.slotStartIso}
                  onSuccess={() => {
                    fetchAppointments("patient");
                  }}
                  trigger={
                    <Button
                      variant="outline"
                      size="sm"
                      className="text-red-600 dark:text-red-400 border-red-200 dark:border-red-800 hover:bg-red-50 dark:hover:bg-red-950/50 font-medium transition-colors"
                    >
                      <XCircle className="w-4 h-4 mr-2"/>
                      Cancel
                    </Button>
                  }
                />
              )}
            </div>

            {appointment.status === 'Completed' && (
              <div className="flex items-center gap-0.5">
                {[...Array(5)].map((_, i) => (
                  <Star
                    key={i}
                    className="w-4 h-4 fill-amber-400 text-amber-400 drop-shadow-sm"
                  />
                ))}
              </div>
            )}
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );

  const EmptyState = ({ tab }: { tab: string }) => {
    const emptyStates = {
      upcoming: {
        icon: Clock,
        title: "No Upcoming Appointments",
        description: "You have no upcoming appointments scheduled. Book your first session with a therapist today.",
        showBookButton: true,
      },
      past: {
        icon: FileText,
        title: "No Past Appointments",
        description: "Your completed consultations will appear here once you've had your first session.",
        showBookButton: false,
      },
    };

    const state = emptyStates[tab as keyof typeof emptyStates];
    const Icon = state.icon;
    return (
      <Card className="border-dashed border-2 bg-linear-to-br from-muted/30 to-transparent">
        <CardContent className="p-12 text-center">
          <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-muted/50 flex items-center justify-center">
            <Icon className="w-10 h-10 text-muted-foreground" />
          </div>
          <h3 className="text-xl font-semibold text-foreground mb-2 tracking-tight font-display">
            {state.title}
          </h3>
          <p className="text-muted-foreground mb-8 max-w-md mx-auto leading-relaxed">{state.description}</p>

          {state.showBookButton && (
            <Link href="/therapists">
              <Button className="shadow-md hover:shadow-lg transition-all duration-200 font-medium">
                <Calendar className="w-4 h-4 mr-2" />
                Book Your First Appointment
              </Button>
            </Link>
          )}
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="min-h-dvh">
      <Header showDashboardNav={true} />

      <div>
        <div className="container mx-auto px-4 py-6">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h1 className="text-xl md:text-3xl font-bold text-foreground tracking-tight font-display">
                My Appointments
              </h1>
              <p className="text-sm md:text-base text-muted-foreground mt-1">
                Manage your healthcare appointments
              </p>
            </div>

            <div className="flex items-center">
              <Link href="/therapists">
                <Button className="shadow-md hover:shadow-lg transition-all duration-200 font-medium">
                  <Calendar className="w-4 h-4 mr-2" />
                  <span className="hidden sm:inline">Book New Appointment</span>
                  <span className="sm:hidden">Book</span>
                </Button>
              </Link>
            </div>
          </div>

          <Tabs
            value={activeTab}
            onValueChange={setActiveTab}
            className="space-y-6"
          >
            <TabsList className="grid w-full grid-cols-2 p-1 bg-muted/50 rounded-xl">
              <TabsTrigger
                value="upcoming"
                className="flex items-center gap-2 font-medium rounded-lg data-[state=active]:bg-background data-[state=active]:shadow-sm transition-all"
              >
                <Clock className="w-4 h-4" />
                <span>Upcoming</span>
                <span className="ml-1 px-2 py-0.5 text-xs rounded-full bg-primary/10 text-primary font-semibold">
                  {upcomingList.length}
                </span>
              </TabsTrigger>
              <TabsTrigger 
                value="past" 
                className="flex items-center gap-2 font-medium rounded-lg data-[state=active]:bg-background data-[state=active]:shadow-sm transition-all"
              >
                <Calendar className="w-4 h-4" />
                <span>Past</span>
