import {test,expect} from 'vitest';
import {observations} from './observations.mjs';
test('E1',()=>{
 for(const [id,target,reason,selected] of [['success-a','a','Schedule conflict — family visit','a'],['success-b','b','Medical appointment; need to reschedule','a']]){
  const o=observations.find(o=>o.id===id);
  expect(o.exception).toBeFalsy();
  const s=JSON.parse(o.text.split('STATE:')[1].split(':ENDSTATE')[0]);
  expect(s.appointments).toHaveLength(2);
  const changed=s.appointments.find(a=>a._id===target);
  expect(changed.status).toBe('Cancelled');
  expect(changed.cancellationReason).toBe(reason);
  const other=s.appointments.find(a=>a._id!==target);
  expect(other.status).toBe('Scheduled');
  expect(other.cancellationReason).toBe('Previous reason '+other._id);
  expect(other.symptoms).toBe('Initial symptoms '+other._id);
  expect(s.currentAppointment).toEqual(s.appointments.find(a=>a._id===selected));
  expect(o.text).toContain('This appointment was cancelled');
  expect(o.text).toContain('Reason: '+reason);
 }
});

import {test,expect} from 'vitest';
import {observations} from './observations.mjs';
test('E2',()=>{const o=observations.find(o=>o.id==='rejected');expect(o.exception).toBeFalsy();const s=JSON.parse(o.text.split('STATE:')[1].split(':ENDSTATE')[0]);expect(s.appointments).toHaveLength(2);for(const a of s.appointments){expect(a.status).toBe('Scheduled');expect(a.cancellationReason).toBe('Previous reason '+a._id);expect(a.symptoms).toBe('Initial symptoms '+a._id);}expect(s.currentAppointment).toEqual(s.appointments.find(a=>a._id==='b'));expect(o.text).toContain('Cancellation Failed');expect(o.text).not.toContain('This appointment was cancelled');});

